/* Guitar voicings are generated from movable shapes and verified in tests. */
(() => {
 const names=['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'];
 const aliases={Db:'C#',Eb:'D#',Gb:'F#',Ab:'G#',Bb:'A#',Cb:'B',Fb:'E','E#':'F','B#':'C'};
 const open={C:[-1,3,2,0,1,0],D:[-1,-1,0,2,3,2],E:[0,2,2,1,0,0],G:[3,2,0,0,0,3],A:[-1,0,2,2,2,0],Am:[-1,0,2,2,1,0],Em:[0,2,2,0,0,0],Dm:[-1,-1,0,2,3,1],Cmaj7:[-1,3,2,0,0,0],D7:[-1,-1,0,2,1,2],A7:[-1,0,2,0,2,0],E7:[0,2,0,1,0,0],G7:[3,2,0,0,0,1],C7:[-1,3,2,3,1,0],B7:[-1,2,1,2,0,2],'C/G':[3,3,2,0,1,0],'D/F#':[2,0,0,2,3,2],'G/B':[-1,2,0,0,3,3],'Am/G':[3,0,2,2,1,0]};
 const shapes={
  '':[[0,2,2,1,0,0],[-1,0,2,2,2,0]],m:[[0,2,2,0,0,0],[-1,0,2,2,1,0]],
  '7':[[0,2,0,1,0,0],[-1,0,2,0,2,0]],m7:[[0,2,0,0,0,0],[-1,0,2,0,1,0]],
  maj7:[[0,2,1,1,0,0],[-1,0,2,1,2,0]],sus4:[[0,2,2,2,0,0],[-1,0,2,2,3,0]],
  sus2:[[0,2,4,4,0,0],[-1,0,2,2,0,0]],dim7:[[0,1,2,0,2,0]],
  add9:[[0,2,4,1,0,0],[-1,0,2,4,2,0]],'5':[[0,2,2,-1,-1,-1],[-1,0,2,2,-1,-1]],
  '6':[[0,2,2,1,2,0],[-1,0,2,2,2,2]],m6:[[0,2,2,0,2,0],[-1,0,2,2,1,2]]
 };
 function voicing(chord){if(open[chord])return open[chord];const m=chord.match(/^([A-G](?:#|b)?)(m|m7|maj7|sus4|sus2|dim7|add9|5|6|m6|7)?$/);if(!m)return null;const root=names.indexOf(aliases[m[1]]||m[1]);const quality=m[2]||'';if(root<0||!shapes[quality])return null;const candidates=shapes[quality].map((shape,i)=>{const shift=(root-(i===0?4:9)+12)%12;return shape.map(f=>f<0?-1:f+shift)});return candidates.sort((a,b)=>Math.max(...a)-Math.max(...b))[0]}
 function diagram(chord){const frets=voicing(chord);if(!frets)return `<div class="chord-unavailable">ဒီ chord အတွက် လက်ကွက်မထည့်ရသေးပါ။<br>Chord နာမည်ကို မူရင်းအတိုင်း ဖော်ပြထားပါတယ်။</div>`;const positive=frets.filter(f=>f>0);const base=Math.max(...frets)<=5?1:Math.min(...positive);const x=i=>35+i*24;const y=f=>50+(f-base+.5)*24;let drawing='';for(let i=0;i<6;i++)drawing+=`<line x1="${x(i)}" y1="50" x2="${x(i)}" y2="170"/>`;for(let f=0;f<=5;f++)drawing+=`<line x1="35" y1="${50+f*24}" x2="155" y2="${50+f*24}" ${f===0&&base===1?'stroke-width="4"':''}/>`;for(let i=0;i<6;i++){if(frets[i]<0)drawing+=`<text x="${x(i)}" y="35" text-anchor="middle">×</text>`;else if(frets[i]===0)drawing+=`<circle cx="${x(i)}" cy="30" r="4" fill="none"/>`;else drawing+=`<circle class="finger-dot" cx="${x(i)}" cy="${y(frets[i])}" r="7"/>`;drawing+=`<text x="${x(i)}" y="192" text-anchor="middle" class="string-name">${['E','A','D','G','B','e'][i]}</text>`}if(base>1)drawing+=`<text x="15" y="67" class="fret-label">${base}</text>`;return `<svg class="guitar-diagram" viewBox="0 0 190 207" role="img" aria-label="${escapeHtml(chord)} guitar chord, frets low E to high e: ${frets.map(f=>f<0?'muted':f).join(', ')}"><g>${drawing}</g></svg><div class="fret-values">${frets.map(f=>f<0?'×':f).join(' · ')}</div>`}
 function showChord(chord){if(!$('#chord-dialog')){document.body.insertAdjacentHTML('beforeend',`<dialog id="chord-dialog" aria-labelledby="chord-dialog-title"><button id="chord-dialog-close" aria-label="Close chord diagram">${window.NyohIcon('close')}</button><span class="eyebrow">GUITAR CHORD REFERENCE</span><h2 id="chord-dialog-title"></h2><div id="chord-drawing"></div><p class="chord-legend">× မတီးရ · ○ ကြိုးလွတ်<br>Standard tuning: E A D G B e</p></dialog>`);$('#chord-dialog-close').onclick=()=>$('#chord-dialog').close();$('#chord-dialog').addEventListener('keydown',e=>{if(e.key==='Escape')e.stopPropagation()})}$('#chord-dialog-title').textContent=chord;$('#chord-drawing').innerHTML=diagram(chord);if(!$('#chord-dialog').open)$('#chord-dialog').showModal()}
 function renderChords(){if(!state.current||!$('#sheet'))return;let panel=$('#chords-used');if(!panel){panel=document.createElement('section');panel.id='chords-used';$('#sheet').before(panel)}const chords=[...new Set([...state.current.chordpro.matchAll(/\[([^\]\n]+)\]/g)].map(m=>m[1].trim()).filter(c=>/^[A-G](?:#|b)?/.test(c)).map(c=>transposeChord(c,state.transpose)))];panel.hidden=state.lyricsOnly||!chords.length;panel.innerHTML=`<div class="chords-heading"><strong>အသုံးပြုထားသော chords <span>${chords.length}</span></strong><small>နှိပ်ပြီး လက်ကွက်ကြည့်ပါ</small></div><div class="chord-chip-list">${chords.map(c=>`<button data-chord="${escapeHtml(c)}" aria-label="${escapeHtml(c)} guitar chord diagram">${escapeHtml(c)}</button>`).join('')}</div>`;panel.querySelectorAll('[data-chord]').forEach(b=>b.onclick=()=>showChord(b.dataset.chord))}
 function exitFocus(){document.body.classList.remove('focus-mode');if($('#focus-exit'))$('#focus-exit').hidden=true;const button=$('#focus-toggle');if(button){button.setAttribute('aria-pressed','false');button.textContent='Focus mode'}}
 function toggleFocus(){if(document.body.classList.contains('focus-mode')){exitFocus();return}document.body.classList.add('focus-mode');if(!$('#focus-exit')){const b=document.createElement('button');b.id='focus-exit';b.textContent='Focus mode ထွက်မယ်';b.onclick=exitFocus;document.body.append(b)}$('#focus-exit').hidden=false;$('#focus-toggle').setAttribute('aria-pressed','true');$('#focus-toggle').textContent='Exit focus';$('#sheet').scrollIntoView({behavior:'smooth',block:'start'})}
 const previousReady=window.Nyoh.songReady;window.Nyoh.songReady=s=>{previousReady(s);const button=document.createElement('button');button.id='focus-toggle';button.textContent='Focus mode';button.setAttribute('aria-pressed',String(document.body.classList.contains('focus-mode')));button.onclick=toggleFocus;$('.reader-tools').append(button);renderChords()};
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('focus-mode')&&!$('#chord-dialog')?.open){exitFocus();e.stopImmediatePropagation()}},true);
 window.TayWinePractice={voicing,diagram,renderChords,exitFocus};
})();
